const staticData = $getWorkflowStaticData('node');
if (!staticData.seenLinks) {
  staticData.seenLinks = [];
}

const seen = new Set(staticData.seenLinks);
const newItems = [];

for (const item of $input.all()) {
  const link = item.json.link;
  if (link && !seen.has(link)) {
    newItems.push(item);
    seen.add(link);
  }
}

// Garde un historique borné pour éviter une croissance illimitée
staticData.seenLinks = Array.from(seen).slice(-500);

return newItems;

