const response = $input.item.json;
const raw = response.content?.[0]?.text?.trim() || '{}';

let analyse;
try {
  analyse = JSON.parse(raw);
} catch (e) {
  analyse = { pertinent: false, score: 0, resume: 'Analyse Claude non exploitable', angle_approche: '' };
}

const source = $('Filtrer les nouveaux éléments').item.json;

return [{
  json: {
    titre: source.title,
    lien: source.link,
    ...analyse
  }
}];

const items = $input.all();

if (items.length === 0) {
  return [];
}

const rows = items.map(i => {
  const d = i.json;
  return `<tr>
    <td><a href="${d.lien}">${d.titre}</a></td>
    <td>${d.score}/5</td>
    <td>${d.client_probable || ''}</td>
    <td>${d.echeance_probable || ''}</td>
    <td>${d.resume || ''}</td>
    <td>${d.angle_approche || ''}</td>
  </tr>`;
}).join('\n');

const html = `<h2>Veille marchés/appels d'offres — ${new Date().toLocaleDateString('fr-FR')}</h2>
<p>${items.length} opportunité(s) pertinente(s) détectée(s) aujourd'hui.</p>
<table border="1" cellpadding="6" cellspacing="0">
<tr><th>Titre</th><th>Score</th><th>Client probable</th><th>Échéance</th><th>Résumé</th><th>Angle d'approche</th></tr>
${rows}
</table>`;

return [{ json: { html, count: items.length } }];
